// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (swap-*) and colors (--swap-*). Mirrored in a right-to-left
// context. React 19 hoists this <style> into <head> once, however many
// instances render.
const css = `
[data-slot="swap-box"] {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 120px;
  aspect-ratio: 1;
}
[data-slot="swap-box"]:dir(rtl) {
  transform: translate(-50%, -50%) scale(-1, 1);
}

[data-slot="swap-front"],
[data-slot="swap-back"] {
  position: absolute;
  inset: 0;
  border-radius: 25%;
}
[data-slot="swap-front"]::before,
[data-slot="swap-front"]::after,
[data-slot="swap-back"]::before,
[data-slot="swap-back"]::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 45%;
  aspect-ratio: 100/18;
  border-radius: 999px;
  background-color: currentColor;
  transform: translate(-50%, -50%);
}
[data-slot="swap-front"] {
  color: var(--swap-front-ink, #fff);
  background-color: var(--swap-front, #999);
  transform-origin: right bottom;
  animation:
    swap-change 0.6s ease-in-out 0.2s both,
    swap-change 0.6s ease-in-out 1.4s reverse forwards;
}
[data-slot="swap-front"]::before {
  transform: translate(-50%, -50%) rotate(90deg);
}
[data-slot="swap-back"] {
  color: var(--swap-back-ink, #999);
  background-color: var(--swap-back, #fff);
  z-index: 1;
}
@keyframes swap-change {
  from,
  50% {
    z-index: 2;
  }
  50.1%,
  to {
    z-index: 0;
  }

  from,
  to {
    transform: rotate(0deg);
  }
  50% {
    transform: rotate(90deg);
  }
}

/*
 * Reduced motion: opacity only. The plus fades out to show the minus, then
 * fades back in, on the same timeline.
 */
@keyframes swap-fade {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="swap-front"] {
    z-index: 2;
    animation:
      swap-fade 0.6s ease-in-out 0.2s both,
      swap-fade 0.6s ease-in-out 1.4s reverse forwards;
  }
}
`;

/**
 * A plus tile flips aside to reveal a minus tile beneath, then flips back on
 * top, once on mount. Remount it (change its `key`) to play it again.
 */
function Swap({ className, ...props }: React.ComponentProps<"div">) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return (
    <div
      data-slot="swap"
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn(
        "relative aspect-square w-full max-w-80 overflow-hidden bg-[var(--swap-surface,#f1f1f1)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-swap" precedence="default">
        {css}
      </style>
      <div data-slot="swap-box">
        <div data-slot="swap-front" />
        <div data-slot="swap-back" />
      </div>
    </div>
  );
}

export { Swap };
